*, *::before, *::after {
  box-sizing: border-box;
}
.rail {
  position: sticky;
  top: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 18px;
  height: 100vh;
  overflow-y: auto;
  padding: 24px;
  border-right: 1px solid var(--border);
  background: #fbfcfd;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.brand div, .field {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 8px;
  color: white;
  background: var(--primary);
  font-weight: 800;
}
.brand strong {
  font-size: 17px;
  overflow-wrap: anywhere;
}
.brand span, .field > span {
  color: var(--muted-foreground);
  font-size: 12px;
  font-weight: 700;
}
.rail-nav {
  display: grid;
  gap: 6px;
}
.rail-nav a, .rail-nav button {
  display: grid;
  gap: 3px;
  width: 100%;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
  min-width: 0;
}
.rail-nav a:hover, .rail-nav a.active,
.rail-nav button:hover, .rail-nav button.active {
  border-color: var(--border);
  background: #eef6f5;
}
.rail-nav strong {
  font-size: 13px;
  overflow-wrap: anywhere;
}
.rail-nav span {
  color: var(--muted-foreground);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.35;
}
.sidebar-footer {
  position: sticky;
  bottom: 0;
  margin-top: auto;
  display: grid;
  gap: 6px;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
}
@media (max-width: 860px) {
  .rail {
    width: 100%;
    height: auto;
    max-width: 100vw;
    padding: 18px;
  }
}

